def get_non_it_roles():
    for role in NON_IT_ROLES:
        role["domain"] = "NON-IT"
        role["id"] = role["title"].lower().replace(" ", "_").replace("/", "").replace(".", "")
        role["icon"] = "fas fa-briefcase" # default icon
        
        # Add basic descriptions for the roles since they were not provided
        role["desc"] = f"Professional role as a {role['title']} in the {role['cat']} sector."
        
        # We assign an icon based on category
        cat = role["cat"]
        if cat == "Engineering & Manufacturing":
            role["icon"] = "fas fa-cogs"
        elif cat == "Construction & Architecture":
            role["icon"] = "fas fa-building"
        elif cat == "Finance, Accounting & Banking":
            role["icon"] = "fas fa-chart-pie"
        elif cat == "Marketing, Sales & Business":
            role["icon"] = "fas fa-bullhorn"
        elif cat == "HR & Administration":
            role["icon"] = "fas fa-users"
        elif cat == "Law":
            role["icon"] = "fas fa-balance-scale"
        elif cat == "Healthcare & Medical":
            role["icon"] = "fas fa-heartbeat"
        elif cat == "Agriculture & Food":
            role["icon"] = "fas fa-leaf"
        elif cat == "Science & Biotechnology":
            role["icon"] = "fas fa-flask"
        elif cat == "Education":
            role["icon"] = "fas fa-chalkboard-teacher"
            
    return NON_IT_ROLES
